1	/**
2	 * Orchestrator main entry point.
3	 *
4	 * Lifecycle:
5	 *   bootstrap (once) → polling loop:
6	 *     pull workspaces → eligibility → claim → briefing → adapter.run →
7	 *     side-effects → sleep → repeat
8	 *
9	 * idle_sleep_seconds controls loop behaviour (read from agent.yaml):
10	 *   0   → single-shot mode: one cycle then exit
11	 *   >0  → continuous: loops indefinitely, sleeping idle_sleep_seconds between cycles
12	 *
13	 * Exit codes:
14	 *   0  normal exit
15	 *   2  agent.yaml invalid
16	 *   3  git clone/pull failed (bootstrap only)
17	 *   4  unexpected fatal error
18	 */
19	
20	import { existsSync, readFileSync, writeFileSync } from "node:fs";
21	import { join } from "node:path";
22	import { tmpdir } from "node:os";
23	import { execSync, spawn } from "node:child_process";
24	import { randomUUID } from "node:crypto";
25	import { parse as parseYaml, stringify as yamlStringify } from "yaml";
26	import { runBootstrap } from "./bootstrap/bootstrap.js";
27	import { resolveSSHKey } from "./resolve-ssh-key.js";
28	import { workspaceYamlPath, taskYamlAbsPath, taskYamlRelPath, taskBranchName, featureBranchName } from "./paths.js";
29	import { runFeatureBranchLifecycle } from "./feature-branch/lifecycle-manager.js";
30	import { findEligibleTasks, findFixableTasks, findReviewableTasks } from "./eligibility/match.js";
31	import { claimTask } from "./claim/claim-task.js";
32	import { claimFixTask } from "./claim/claim-fix-task.js";
33	import { openWorkspacePr } from "./claim/open-workspace-pr.js";
34	import type { Task, TaskLogEntry } from "./types/task.js";
35	import { generateBriefing } from "./briefing/agent-context.js";
36	import { generateFixBriefing, extractPrUrlFromTask } from "./briefing/fix-briefing.js";
37	import { fetchRagContext } from "./bootstrap/fetch-rag-context.js";
38	import { resolveModel } from "./config/resolve-model-policy.js";
39	import { parseModelOverrides } from "./config/parse-model-overrides.js";
40	import {
41	  resolveRepoLocalPath,
42	  resolveRepoBaseBranch,
43	  resolveRepoGitUrl,
44	  loadWorkspaceModelPolicy,
45	  parseManagementRepoCoords,
46	} from "./config/workspace-config.js";
47	import { pullWorkspaces } from "./poll/pull-workspaces.js";
48	import { runAgentLoop, type CycleOutcome } from "./poll/agent-loop.js";
49	import { runReapLoop } from "./poll/reap-loop.js";
50	import { checkInReviewPrs } from "./poll/check-in-review-prs.js";
51	import { handleMergeConflicts } from "./pr-response/auto-rebase.js";
52	import { dispatchReviewer } from "./pr-response/dispatch-reviewer.js";
53	import { handleMergedPrs, handleWorkspacePrRecoveries } from "./poll/handle-merged-prs.js";
54	import { runStateInvariantCheck } from "./poll/state-invariant-checker.js";
55	import type { ExecutorPortInput } from "@workflow/runtime-abi";
56	import { buildGitEnv } from "./git-env.js";
57	import { mutateTaskYaml } from "./side-effects/mutate-task-yaml.js";
58	import { createLocalSubprocessProfile } from "./profiles/local-subprocess.js";
59	import { createLocalDockerProfile } from "./profiles/local-docker.js";
60	import type { RuntimePorts } from "./runtime-ports.js";
61	import { SubProcessAdapter } from "./adapters/executor/subprocess.js";
62	import { InMemoryBrokerAdapter } from "./adapters/broker/in-memory.js";
63	
64	// ── Helpers ───────────────────────────────────────────────────────────────────
65	
66	/**
67	 * Returns an invokeClaudeForResolution function that pins Claude to a specific model.
68	 * Passed to all conflict-resolution handlers so they respect workspace model_policy
69	 * instead of defaulting to whatever the Claude CLI ships with.
70	 */
71	function makeConflictResolver(
72	  model: string,
73	  maxTurns = 10,
74	): (prompt: string, cwd: string, env: NodeJS.ProcessEnv) => Promise<boolean> {
75	  return (prompt, cwd, env) =>
76	    new Promise((resolve) => {
77	      const child = spawn(
78	        "claude",
79	        [
80	          "-p", prompt,
81	          "--model", model,
82	          "--max-turns", String(maxTurns),
83	          "--output-format", "stream-json",
84	          "--verbose",
85	          "--dangerously-skip-permissions",
86	        ],
87	        { cwd, env, stdio: ["ignore", "pipe", "pipe"] },
88	      );
89	      child.stdout.pipe(process.stdout);
90	      child.stderr.pipe(process.stderr);
91	      child.on("close", (code) => resolve(code === 0));
92	      child.on("error", () => resolve(false));
93	    });
94	}
95	
96	function requireEnv(name: string): string {
97	  const val = process.env[name];
98	  if (!val) throw new Error(`Required environment variable ${name} is not set`);
99	  return val;
100	}
101	
102	function extractRepoName(url: string): string {
103	  const match = /\/([^/]+?)(?:\.git)?$/.exec(url);
104	  return match?.[1] ?? url;
105	}
106	
107	/** Emit a structured JSON event via the profile's EventEmitterPort. */
108	function makeEmit(ports: RuntimePorts): (event: Record<string, unknown>) => void {
109	  return (event: Record<string, unknown>) => {
110	    const { type, ...data } = event as { type?: string } & Record<string, unknown>;
111	    ports.emitter.emit(type ?? "event", data);
112	  };
113	}
114	
115	function resolveTaskRepoId(workspaceRoot: string, featureId: string, taskId: string): string {
116	  const task = parseYaml(
117	    readFileSync(taskYamlAbsPath(workspaceRoot, featureId, taskId), "utf-8"),
118	  ) as { repo: string };
119	  if (!task.repo) throw new Error(`Task ${taskId} has no repo field`);
120	  return task.repo;
121	}
122	
123	interface TaskContext {
124	  taskRepoRoot: string;
125	  taskRepoUrl: string;
126	  taskBaseBranch: string;
127	  implementationModel: string;
128	}
129	
130	function resolveTaskContext(
131	  workspaceLocalPath: string,
132	  featureId: string,
133	  task: Task,
134	): TaskContext {
135	  const workspaceModelPolicy = loadWorkspaceModelPolicy(workspaceLocalPath);
136	  const taskRepoRoot = resolveRepoLocalPath(workspaceLocalPath, task.repo);
137	  const taskRepoUrl = resolveRepoGitUrl(workspaceLocalPath, task.repo);
138	  const taskBaseBranch = resolveRepoBaseBranch(workspaceLocalPath, task.repo);
139	
140	  const tasksMdPath = join(workspaceLocalPath, "docs", "features", featureId, "tasks.md");
141	  let taskModelOverrides = {};
142	  try {
143	    taskModelOverrides = parseModelOverrides(readFileSync(tasksMdPath, "utf-8"), task.id);
144	  } catch { /* non-fatal */ }
145	
146	  const implementationModel = resolveModel(
147	    workspaceModelPolicy,
148	    taskModelOverrides,
149	    "implementation",
150	    task.id,
151	  );
152	
153	  return { taskRepoRoot, taskRepoUrl, taskBaseBranch, implementationModel };
154	}
155	
156	/**
157	 * Write a rag_pre_flight log entry to the task YAML before spawning the executor.
158	 * Commits and pushes to the task branch. Throws on error.
159	 */
160	function writeRagPreFlight(
161	  workspaceRoot: string,
162	  featureId: string,
163	  taskId: string,
164	  taskBranch: string,
165	  gitAuthorEmail: string,
166	  gitAuthorName: string,
167	  sshKeyPath: string | undefined,
168	  ragPreFlight: { query: string; injected: boolean; summary: string },
169	): void {
170	  const now = new Date().toISOString();
171	  const entry: TaskLogEntry = {
172	    action: "rag_pre_flight",
173	    by: gitAuthorEmail,
174	    at: now,
175	    rag_context_injected: ragPreFlight.injected,
176	    rag_summary: ragPreFlight.summary,
177	    rag_query: ragPreFlight.query,
178	    note: "Runtime pre-flight RAG fetch — written before executor spawn.",
179	  };
180	
181	  const yamlPath = taskYamlAbsPath(workspaceRoot, featureId, taskId);
182	  const relPath = taskYamlRelPath(featureId, taskId);
183	  const gitOpts = {
184	    cwd: workspaceRoot,
185	    encoding: "utf-8" as const,
186	    env: buildGitEnv(sshKeyPath, { email: gitAuthorEmail, name: gitAuthorName }),
187	    timeout: 30_000,
188	    stdio: "pipe" as const,
189	  };
190	
191	  // Anchor to the task branch tip before reading/writing — same pattern as
192	  // append-log and mutate-task-yaml. Defensive: claimTask leaves the repo on
193	  // the task branch, but an explicit anchor makes this function self-contained.
194	  execSync(`git fetch origin "${taskBranch}"`, gitOpts);
195	  execSync(`git checkout -B "${taskBranch}" "origin/${taskBranch}"`, gitOpts);
196	
197	  const task = parseYaml(readFileSync(yamlPath, "utf-8")) as Task;
198	  task.log.push(entry);
199	  writeFileSync(yamlPath, yamlStringify(task), "utf-8");
200	
201	  execSync(`git add "${relPath}"`, gitOpts);
202	  execSync(
203	    `git commit -m "chore(${taskId}): rag pre-flight — ${ragPreFlight.injected ? "injected" : "skipped"}"`,
204	    gitOpts,
205	  );
206	  execSync(`git push origin "${taskBranch}"`, gitOpts);
207	}
208	
209	// ── Main ──────────────────────────────────────────────────────────────────────
210	
211	async function main(): Promise<number> {
212	  let agentYamlPath: string;
213	  let workflowLocalPath: string;
214	  let workspacesRoot: string;
215	  let gitAuthorEmail: string;
216	
217	  // Bootstrap-time emit — before the profile is ready, write directly to stdout.
218	  const bootstrapEmit = (event: Record<string, unknown>) => {
219	    console.log(JSON.stringify({ at: new Date().toISOString(), ...event }));
220	  };
221	
222	  try {
223	    agentYamlPath = requireEnv("AGENT_YAML_PATH");
224	    workflowLocalPath = requireEnv("WORKFLOW_LOCAL_PATH");
225	    workspacesRoot = requireEnv("WORKSPACES_ROOT");
226	    gitAuthorEmail = requireEnv("GIT_AUTHOR_EMAIL");
227	  } catch (e) {
228	    bootstrapEmit({ type: "fatal_missing_env", details: (e as Error).message });
229	    return 4;
230	  }
231	
232	  const gitAuthorName = process.env.GIT_AUTHOR_NAME ?? gitAuthorEmail;
233	
234	  const sshResolution = resolveSSHKey(process.env);
235	  const sshKeyPath = sshResolution.sshKeyPath;
236	
237	  // ── Create the runtime profile ────────────────────────────────────────────────
238	  // RUNTIME_PROFILE selects the adapter set. Switching profiles at startup is how
239	  // new infra is added without core changes.
240	  //   local-subprocess (default) — executor + in-process broker in one container
241	  //   local-docker               — docker run -d executor + shared Redis broker (M:N)
242	  const runtimeProfile = process.env.RUNTIME_PROFILE ?? "local-subprocess";
243	  const ports: RuntimePorts & { broker: { start(): Promise<number>; stop(): Promise<void>; getCallbackUrl(): string | null } } =
244	    runtimeProfile === "local-docker"
245	      ? createLocalDockerProfile({
246	          gitAuthorEmail,
247	          gitAuthorName,
248	          sshKeyPath,
249	          brokerUrl: process.env.BROKER_URL ?? "http://broker:7000",
250	        })
251	      : createLocalSubprocessProfile({
252	          gitAuthorEmail,
253	          gitAuthorName,
254	          sshKeyPath,
255	        });
256	
257	  // Start the broker receiver (no-op for HttpBrokerAdapter; binds HTTP port for InMemoryBrokerAdapter).
258	  const brokerPort = await ports.broker.start();
259	
260	  const emit = makeEmit(ports);
261	  emit({ type: "broker_started", port: brokerPort, callback_url: ports.broker.getCallbackUrl() });
262	
263	  if (sshResolution.warned) {
264	    emit({ type: "warn_no_ssh_key", note: "SSH_PRIVATE_KEY is not set — git operations over SSH will fail." });
265	  }
266	
267	  const bootstrapResult = await runBootstrap({
268	    agentYamlPath,
269	    workflowLocalPath,
270	    workflowUrl: process.env.WORKFLOW_URL,
271	    workspacesRoot,
272	    sshKeyPath,
273	  });
274	
275	  if (bootstrapResult.exitCode !== 0) return bootstrapResult.exitCode;
276	
277	  const config = bootstrapResult.config!;
278	  const githubToken = process.env.GITHUB_TOKEN ?? "";
279	  if (!githubToken) emit({ type: "warn_no_github_token" });
280	
281	  // ── Feature Branch Lifecycle Manager (T8) ────────────────────────────────────
282	  // Runs once at startup — creates or syncs feature/{featureId} on each watched
283	  // workspace before the main dispatch loop begins.
284	  for (const watchUrl of config.watches) {
285	    const workspaceLocalPath = join(workspacesRoot, extractRepoName(watchUrl));
286	    if (!existsSync(workspaceLocalPath)) continue;
287	    try {
288	      const mgmtCoords = parseManagementRepoCoords(workspaceLocalPath);
289	      runFeatureBranchLifecycle({
290	        workspaceRoot: workspaceLocalPath,
291	        baseBranch: mgmtCoords.baseBranch,
292	        gitAuthorEmail,
293	        gitAuthorName,
294	        sshKeyPath,
295	        emit,
296	      });
297	    } catch (e) {
298	      emit({ type: "feature_branch_lifecycle_workspace_error", workspace: watchUrl, details: String(e) });
299	    }
300	  }
301	
302	  let lastPrPollAt: number | null = null;
303	  // Local counter for local-docker mode — tracks how many executor containers are
304	  // in-flight. Incremented on submit, decremented when the reap loop acks a completion.
305	  // TODO: replace with broker.registrySize() once the broker exposes that endpoint.
306	  let dockerInFlight = 0;
307	  let cycleCount = 0;
308	  const stateInvariantCheckInterval = parseInt(
309	    process.env.STATE_INVARIANT_CHECK_INTERVAL ?? "5",
310	    10,
311	  );
312	
313	  async function buildAndSubmitExecutor(opts: {
314	    task: Task;
315	    featureId: string;
316	    workspaceId: string;
317	    taskRepoUrl: string;
318	    taskBranch: string;
319	    taskRepoRoot: string;
320	    implementationModel: string;
321	    briefingPath: string;
322	    resultPath: string;
323	    workspaceLocalPath: string;
324	  }) {
325	    const { task, featureId, workspaceId, taskRepoUrl, taskBranch, taskRepoRoot,
326	            implementationModel, briefingPath, resultPath, workspaceLocalPath } = opts;
327	
328	    const nonce = randomUUID();
329	    const callbackUrl = ports.broker.getCallbackUrl() ?? "";
330	
331	    const execInput: ExecutorPortInput = {
332	      taskId: task.id,
333	      featureId,
334	      workspaceId,
335	      taskRepoUrl,
336	      taskRepoBranch: taskBranch,
337	      taskRepoPath: taskRepoRoot,
338	      briefingPath,
339	      resultPath,
340	      budgetTokens: config.budget.max_tokens_per_task,
341	      implementationModel,
342	      sshPrivateKey: process.env.SSH_PRIVATE_KEY ?? "",
343	      githubToken,
344	      callbackUrl,
345	      nonce,
346	    };
347	
348	    const extraEnv: Record<string, string> = {
349	      WORKSPACE_ROOT: workspaceLocalPath,
350	      TASK_BRANCH: taskBranch,
351	      GIT_AUTHOR_EMAIL: gitAuthorEmail,
352	      GIT_AUTHOR_NAME: gitAuthorName,
353	      WORKFLOW_LOCAL_PATH: workflowLocalPath,
354	      MAX_TURNS: String(config.budget.max_iterations),
355	      LOG_SINK_ENABLED: config.log_sink.enabled ? "1" : "0",
356	      ...(process.env.MCP_RAG_URL ? { MCP_RAG_URL: process.env.MCP_RAG_URL } : {}),
357	      ...(process.env.FIGMA_PERSONAL_ACCESS_TOKEN
358	        ? { FIGMA_PERSONAL_ACCESS_TOKEN: process.env.FIGMA_PERSONAL_ACCESS_TOKEN }
359	        : {}),
360	    };
361	
362	    const adapter =
363	      runtimeProfile === "local-docker"
364	        ? new (await import("./adapters/executor/docker-run.js")).DockerRunAdapter({
365	            broker: ports.broker,
366	            extraEnv,
367	          })
368	        : new SubProcessAdapter({
369	            broker: ports.broker,
370	            extraEnv,
371	          });
372	
373	    return adapter.submit(execInput);
374	  }
375	
376	  async function runOneCycle(): Promise<CycleOutcome> {
377	    // In local-subprocess mode all repos share the same container filesystem.
378	    // If an executor is running, skip impl repo pulls — syncRepo would switch
379	    // the shared working tree to the base branch and hard-reset it, destroying
380	    // any uncommitted work the executor has in flight.
381	    const execInFlight =
382	      runtimeProfile === "local-subprocess"
383	        ? (ports.broker as InMemoryBrokerAdapter).registrySize() > 0
384	        : false;
385	
386	    const pullResults = pullWorkspaces({
387	      watchUrls: config.watches,
388	      sshKeyPath,
389	      workspacesRoot,
390	      workflowUrl: process.env.WORKFLOW_URL,
391	      workflowLocalPath,
392	      skipImplRepoPull: execInFlight,
393	      emit,
394	    });
395	
396	    const haltedUrls = new Set(
397	      pullResults
398	        .filter((r) => r.outcome === "halt" || r.outcome === "warn")
399	        .map((r) => r.url),
400	    );
401	
402	    let outcome: CycleOutcome = "idle";
403	    const pulledWorkspaceRoots: string[] = [];
404	
405	    // ── Subprocess concurrency guard + task dispatch ──────────────────────────
406	    // In local-subprocess mode all repos share the same container filesystem.
407	    // Two concurrent subprocesses can race on git checkouts in the same repo.
408	    // Wrap the dispatch loop in a labeled block so we can break out of it
409	    // (skipping to PR poll + reap) when a subprocess is already in-flight.
410	    dispatchBlock: {
411	      const defaultMax = runtimeProfile === "local-subprocess" ? 1 : 4;
412	      const maxConcurrent = config.max_concurrent_executors ?? defaultMax;
413	
414	      if (runtimeProfile === "local-subprocess") {
415	        const inFlight = (ports.broker as InMemoryBrokerAdapter).registrySize();
416	        if (inFlight >= maxConcurrent) {
417	          emit({ type: "executor_pool_full", in_flight: inFlight, max: maxConcurrent });
418	          break dispatchBlock;
419	        }
420	      } else if (runtimeProfile === "local-docker") {
421	        if (dockerInFlight >= maxConcurrent) {
422	          emit({ type: "executor_pool_full", in_flight: dockerInFlight, max: maxConcurrent });
423	          break dispatchBlock;
424	        }
425	      }
426	
427	    outerLoop:
428	    for (const watchUrl of config.watches) {
429	      if (haltedUrls.has(watchUrl)) continue;
430	
431	      const workspaceLocalPath = join(workspacesRoot, extractRepoName(watchUrl));
432	      pulledWorkspaceRoots.push(workspaceLocalPath);
433	
434	      if (!existsSync(workspaceLocalPath)) {
435	        emit({ type: "workspace_not_found", workspace_url: watchUrl });
436	        continue;
437	      }
438	
439	      let eligibleTasks;
440	      try {
441	        eligibleTasks = findEligibleTasks(config, workspaceLocalPath, workflowLocalPath);
442	      } catch (e) {
443	        emit({ type: "eligibility_error", workspace_url: watchUrl, details: String(e) });
444	        continue;
445	      }
446	
447	      if (eligibleTasks.length === 0) {
448	        emit({ type: "no_eligible_tasks", workspace_url: watchUrl });
449	        continue;
450	      }
451	
452	      for (const { task, featureId } of eligibleTasks) {
453	        const claimResult = await claimTask({
454	          workspaceRoot: workspaceLocalPath,
455	          taskId: task.id,
456	          featureId,
457	          gitAuthorEmail,
458	          gitAuthorName,
459	          sshKeyPath,
460	          jitterMaxSeconds: config.jitter_max_seconds,
461	        });
462	
463	        const taskBranch = taskBranchName(featureId, task.id);
464	
465	        if (!claimResult.won) {
466	          if (claimResult.reason !== "branch_blocked_recovery") {
467	            emit({ type: "claim_lost", task_id: task.id, feature_id: featureId, reason: claimResult.reason });
468	            continue;
469	          }
470	          emit({ type: "task_blocked_recovery_detected", task_id: task.id, feature_id: featureId });
471	        } else {
472	          emit({ type: "task_claimed", task_id: task.id, feature_id: featureId });
473	        }
474	
475	        // ── Open management-repo PR ───────────────────────────────────────────
476	        if (githubToken) {
477	          try {
478	            const mgmtCoords = parseManagementRepoCoords(workspaceLocalPath);
479	            await openWorkspacePr({
480	              workspaceRoot: workspaceLocalPath,
481	              featureId,
482	              taskId: task.id,
483	              branch: taskBranch,
484	              // Task PRs target the feature branch so all task changes collect
485	              // there before the Handoff Trigger merges to the base branch (T8).
486	              baseBranch: featureBranchName(featureId),
487	              githubToken,
488	              repoOwner: mgmtCoords.owner,
489	              repoName: mgmtCoords.repo,
490	              gitAuthorEmail,
491	              gitAuthorName,
492	              sshKeyPath,
493	            });
494	            emit({ type: "workspace_pr_opened", task_id: task.id, feature_id: featureId });
495	          } catch (e) {
496	            const stderr = (e as { stderr?: Buffer | string }).stderr;
497	            const stderrStr = stderr instanceof Buffer ? stderr.toString("utf-8") : (stderr ?? "");
498	            emit({ type: "workspace_pr_failed", task_id: task.id, feature_id: featureId, details: String(e), stderr: stderrStr });
499	          }
500	        }
501	
502	        // ── Resolve model + task repo ────────────────────────────────────────
503	        const { taskRepoRoot, taskRepoUrl, taskBaseBranch, implementationModel } =
504	          resolveTaskContext(workspaceLocalPath, featureId, task);
505	
506	        // ── RAG pre-flight ───────────────────────────────────────────────────
507	        const mcpRagUrl = process.env.MCP_RAG_URL;
508	        const workspaceYaml = parseYaml(
509	          readFileSync(workspaceYamlPath(workspaceLocalPath), "utf-8"),
510	        ) as { workspace_id: string };
511	        const ragQuery = `${task.title} ${featureId}`;
512	        const ragPreFlight = await fetchRagContext(mcpRagUrl, ragQuery, workspaceYaml.workspace_id);
513	
514	        try {
515	          writeRagPreFlight(
516	            workspaceLocalPath,
517	            featureId,
518	            task.id,
519	            taskBranch,
520	            gitAuthorEmail,
521	            gitAuthorName,
522	            sshKeyPath,
523	            { query: ragQuery, injected: ragPreFlight.injected, summary: ragPreFlight.summary },
524	          );
525	        } catch (e) {
526	          const details = String(e);
527	          emit({ type: "rag_pre_flight_failed", task_id: task.id, feature_id: featureId, details });
528	          mutateTaskYaml({
529	            workspaceRoot: workspaceLocalPath,
530	            featureId,
531	            taskId: task.id,
532	            taskBranch,
533	            result: { terminal_status: "failed", blocked_reason: `rag_pre_flight_error: ${details}` },
534	            gitAuthorEmail,
535	            gitAuthorName,
536	            sshKeyPath,
537	          });
538	          continue;
539	        }
540	
541	        // ── Generate briefing ────────────────────────────────────────────────
542	        const resultPath = join(tmpdir(), `executor-result-${task.id}.json`);
543	        const baseContext = generateBriefing({
544	          taskId: task.id,
545	          featureId,
546	          taskTitle: task.title,
547	          taskBranch,
548	          taskRepo: task.repo,
549	          taskRepoRoot,
550	          workspaceRoot: workspaceLocalPath,
551	          gitAuthorEmail,
552	          gitAuthorName,
553	          implementationModel,
554	          resultPath,
555	        });
556	        const briefingContent = ragPreFlight.block
557	          ? `${baseContext}\n\n${ragPreFlight.block}`
558	          : baseContext;
559	
560	        // ── Write briefing via BriefingTransportPort ─────────────────────────
561	        // Use taskId as the briefing handle so the file path matches the
562	        // existing briefing-{taskId}/briefing.md convention.
563	        const briefingPath = await ports.briefing.put(task.id, briefingContent);
564	
565	        // ── Submit executor (async — T6) ─────────────────────────────────────
566	        const execHandle = await buildAndSubmitExecutor({
567	          task, featureId, workspaceId: workspaceYaml.workspace_id,
568	          taskRepoUrl, taskBranch, taskRepoRoot, implementationModel,
569	          briefingPath, resultPath, workspaceLocalPath,
570	        });
571	
572	        // Persist handle to task YAML for broker crash-recovery reconciliation.
573	        try {
574	          await ports.workflowState.persistHandle(workspaceLocalPath, featureId, task.id, execHandle);
575	        } catch (e) {
576	          emit({ type: "persist_handle_failed", task_id: task.id, feature_id: featureId, details: String(e) });
577	        }
578	
579	        emit({ type: "executor_submitted", task_id: task.id, feature_id: featureId, handle: execHandle });
580	        if (runtimeProfile === "local-docker") dockerInFlight++;
581	        outcome = "ran_task";
582	        break outerLoop;
583	      }
584	    }
585	
586	    // ── Fix-agent dispatch ────────────────────────────────────────────────────
587	    if (outcome !== "ran_task") {
588	      fixLoop:
589	      for (const watchUrl of config.watches) {
590	        if (haltedUrls.has(watchUrl)) continue;
591	
592	        const workspaceLocalPath = join(workspacesRoot, extractRepoName(watchUrl));
593	        if (!existsSync(workspaceLocalPath)) continue;
594	
595	        let fixableTasks;
596	        try {
597	          fixableTasks = findFixableTasks(config, workspaceLocalPath);
598	        } catch (e) {
599	          emit({ type: "eligibility_error", workspace_url: watchUrl, details: String(e) });
600	          continue;
601	        }
602	
603	        for (const { task, featureId } of fixableTasks) {
604	          const taskBranch = taskBranchName(featureId, task.id);
605	          const claimResult = await claimFixTask({
606	            workspaceRoot: workspaceLocalPath,
607	            taskId: task.id,
608	            featureId,
609	            gitAuthorEmail,
610	            gitAuthorName,
611	            jitterMaxSeconds: config.jitter_max_seconds,
612	          });
613	
614	          if (!claimResult.won) {
615	            emit({ type: "fix_claim_lost", task_id: task.id, feature_id: featureId, reason: claimResult.reason });
616	            continue;
617	          }
618	
619	          emit({ type: "fix_task_claimed", task_id: task.id, feature_id: featureId });
620	
621	          const { taskRepoRoot, taskRepoUrl, implementationModel } = resolveTaskContext(workspaceLocalPath, featureId, task);
622	          const fixWsYaml = parseYaml(
623	            readFileSync(workspaceYamlPath(workspaceLocalPath), "utf-8"),
624	          ) as { workspace_id: string };
625	
626	          const resultPath = join(tmpdir(), `executor-result-${task.id}.json`);
627	          const prUrl = extractPrUrlFromTask(task);
628	          const fixContext = generateFixBriefing({
629	            taskId: task.id,
630	            featureId,
631	            taskTitle: task.title,
632	            taskBranch,
633	            taskRepo: task.repo,
634	            taskRepoRoot,
635	            workspaceRoot: workspaceLocalPath,
636	            prUrl: prUrl ?? "",
637	            gitAuthorEmail,
638	            gitAuthorName,
639	            implementationModel,
640	            resultPath,
641	          });
642	
643	          emit({ type: "fix_briefing_generated", task_id: task.id, feature_id: featureId, pr_url: prUrl });
644	          const fixBriefingPath = await ports.briefing.put(task.id, fixContext);
645	          const fixHandle = await buildAndSubmitExecutor({
646	            task, featureId, workspaceId: fixWsYaml.workspace_id,
647	            taskRepoUrl, taskBranch, taskRepoRoot: taskRepoRoot, implementationModel,
648	            briefingPath: fixBriefingPath, resultPath, workspaceLocalPath,
649	          });
650	          emit({ type: "fix_executor_submitted", task_id: task.id, feature_id: featureId, handle: fixHandle });
651	          if (runtimeProfile === "local-docker") dockerInFlight++;
652	          outcome = "ran_task";
653	          break fixLoop;
654	        }
655	      }
656	    }
657	
658	    // ── Reviewer dispatch ─────────────────────────────────────────────────────
659	    if (outcome !== "ran_task") {
660	      reviewerLoop:
661	      for (const watchUrl of config.watches) {
662	        if (haltedUrls.has(watchUrl)) continue;
663	
664	        const workspaceLocalPath = join(workspacesRoot, extractRepoName(watchUrl));
665	        if (!existsSync(workspaceLocalPath)) continue;
666	
667	        let reviewableTasks;
668	        try {
669	          reviewableTasks = findReviewableTasks(config, workspaceLocalPath);
670	        } catch (e) {
671	          emit({ type: "eligibility_error", workspace_url: watchUrl, details: String(e) });
672	          continue;
673	        }
674	
675	        for (const { task, featureId } of reviewableTasks) {
676	          const taskBranch = taskBranchName(featureId, task.id);
677	          const { taskRepoRoot, taskRepoUrl, implementationModel } = resolveTaskContext(workspaceLocalPath, featureId, task);
678	          const wsModelPolicy = loadWorkspaceModelPolicy(workspaceLocalPath);
679	          const revWsYaml = parseYaml(
680	            readFileSync(workspaceYamlPath(workspaceLocalPath), "utf-8"),
681	          ) as { workspace_id: string };
682	          let reviewModelOverrides = {};
683	          try {
684	            const tMdPath = join(workspaceLocalPath, "docs", "features", featureId, "tasks.md");
685	            reviewModelOverrides = parseModelOverrides(readFileSync(tMdPath, "utf-8"), task.id);
686	          } catch { /* non-fatal */ }
687	          const reviewerModel = resolveModel(wsModelPolicy, reviewModelOverrides, "self_review", task.id);
688	
689	          const dispatchResult = await dispatchReviewer({
690	            workspaceRoot: workspaceLocalPath,
691	            featureId,
692	            taskId: task.id,
693	            taskBranch,
694	            implRepoRoot: taskRepoRoot,
695	            implRepoUrl: taskRepoUrl,
696	            gitAuthorEmail,
697	            gitAuthorName,
698	            workflowLocalPath,
699	            maxTurns: config.budget.max_iterations,
700	            maxTokens: config.budget.max_tokens_per_task,
701	            logSinkEnabled: config.log_sink.enabled,
702	            reviewerModel,
703	            workspaceId: revWsYaml.workspace_id,
704	            githubToken,
705	            broker: ports.broker,
706	            callbackUrl: ports.broker.getCallbackUrl() ?? "",
707	            emit,
708	          });
709	
710	          if (dispatchResult === "dispatched") {
711	            if (runtimeProfile === "local-docker") dockerInFlight++;
712	            outcome = "ran_task";
713	            break reviewerLoop;
714	          }
715	        }
716	      }
717	    }
718	    } // end dispatchBlock
719	
720	    // ── In-review PR poll ─────────────────────────────────────────────────────
721	    // In local-subprocess mode the executor subprocess shares the same container
722	    // filesystem as the orchestrator. Both can race on `git rebase` in the same
723	    // repo — a second rebase operation fails with "rebase-merge directory already
724	    // exists". Re-check in-flight count here (not just in dispatchBlock) because
725	    // pulledWorkspaceRoots is already populated on the same cycle that dispatched
726	    // the executor; the dispatchBlock early-break only fires on *subsequent* cycles.
727	    const skipPrPoll =
728	      runtimeProfile === "local-subprocess" &&
729	      (ports.broker as InMemoryBrokerAdapter).registrySize() > 0;
730	    if (githubToken && !skipPrPoll) {
731	      const prPollIntervalMs =
732	        (config.pr_poll_interval_seconds ?? config.idle_sleep_seconds ?? 60) * 1000;
733	      const now = Date.now();
734	
735	      if (lastPrPollAt === null || now - lastPrPollAt >= prPollIntervalMs) {
736	        if (pulledWorkspaceRoots.length > 0) lastPrPollAt = now;
737	        try {
738	          const { prResults, workspacePrRecoveries } = await checkInReviewPrs({
739	            workspaceRoots: pulledWorkspaceRoots,
740	            githubToken,
741	            emit,
742	          });
743	
744	          for (const wsRoot of pulledWorkspaceRoots) {
745	            const wsResults = prResults.filter((r) => r.workspaceRoot === wsRoot);
746	            if (wsResults.some((r) => r.mergeable === false)) {
747	              const wsModelPolicy = loadWorkspaceModelPolicy(wsRoot);
748	              const conflictModel = resolveModel(wsModelPolicy, {}, "conflict_resolution", "conflict-resolver");
749	              await handleMergeConflicts({
750	                prResults: wsResults,
751	                workspaceRoot: wsRoot,
752	                resolveImplRepoRoot: (repoId) => resolveRepoLocalPath(wsRoot, repoId),
753	                resolveImplBaseBranch: (repoId) => resolveRepoBaseBranch(wsRoot, repoId),
754	                resolveTaskRepoId: (fId, tId) => resolveTaskRepoId(wsRoot, fId, tId),
755	                gitAuthorEmail,
756	                gitAuthorName,
757	                sshKeyPath,
758	                emit,
759	                invokeClaudeForResolution: makeConflictResolver(conflictModel),
760	              });
761	            }
762	          }
763	
764	          for (const wsRoot of pulledWorkspaceRoots) {
765	            const wsResults = prResults.filter((r) => r.workspaceRoot === wsRoot);
766	            if (wsResults.some((r) => r.merged === true)) {
767	              const wsModelPolicy = loadWorkspaceModelPolicy(wsRoot);
768	              const conflictModel = resolveModel(wsModelPolicy, {}, "conflict_resolution", "conflict-resolver");
769	              const mgmtCoords = parseManagementRepoCoords(wsRoot);
770	              await handleMergedPrs({
771	                prResults: wsResults,
772	                workspaceRoot: wsRoot,
773	                mgmtRepoOwner: mgmtCoords.owner,
774	                mgmtRepoName: mgmtCoords.repo,
775	                mgmtBaseBranch: mgmtCoords.baseBranch,
776	                githubToken,
777	                gitAuthorEmail,
778	                gitAuthorName,
779	                sshKeyPath,
780	                emit,
781	                invokeClaudeForResolution: makeConflictResolver(conflictModel),
782	              });
783	            }
784	          }
785	
786	          for (const wsRoot of pulledWorkspaceRoots) {
787	            const wsRecoveries = workspacePrRecoveries.filter((r) => r.workspaceRoot === wsRoot);
788	            if (wsRecoveries.length > 0) {
789	              const wsModelPolicy = loadWorkspaceModelPolicy(wsRoot);
790	              const conflictModel = resolveModel(wsModelPolicy, {}, "conflict_resolution", "conflict-resolver");
791	              const mgmtCoords = parseManagementRepoCoords(wsRoot);
792	              await handleWorkspacePrRecoveries({
793	                recoveries: wsRecoveries,
794	                mgmtRepoOwner: mgmtCoords.owner,
795	                mgmtRepoName: mgmtCoords.repo,
796	                mgmtBaseBranch: mgmtCoords.baseBranch,
797	                githubToken,
798	                gitAuthorEmail,
799	                gitAuthorName,
800	                sshKeyPath,
801	                emit,
802	                invokeClaudeForResolution: makeConflictResolver(conflictModel),
803	              });
804	            }
805	          }
806	        } catch (e) {
807	          emit({ type: "in_review_poll_error", details: String(e) });
808	        }
809	      }
810	    }
811	
812	    // ── State invariant checker (every N cycles) ──────────────────────────────
813	    cycleCount++;
814	    if (cycleCount % stateInvariantCheckInterval === 0) {
815	      for (const wsRoot of pulledWorkspaceRoots) {
816	        try {
817	          await runStateInvariantCheck({
818	            workspaceRoot: wsRoot,
819	            githubToken,
820	            gitAuthorEmail,
821	            gitAuthorName,
822	            sshKeyPath,
823	            emit,
824	          });
825	        } catch (e) {
826	          emit({ type: "state_invariant_check_error", workspace: wsRoot, details: String(e) });
827	        }
828	      }
829	    }
830	
831	    // ── Shared reap loop ──────────────────────────────────────────────────────
832	    // Drain completions posted by in-flight executors this cycle (and any
833	    // leftovers from previous cycles). Routes by handle.kind → dispatcher.
834	    try {
835	      const reapResult = await runReapLoop({
836	        broker: ports.broker,
837	        workspaceRoots: pulledWorkspaceRoots,
838	        gitAuthorEmail,
839	        gitAuthorName,
840	        sshKeyPath,
841	        githubToken,
842	        emit,
843	      });
844	      if (reapResult.dispatched > 0) {
845	        if (runtimeProfile === "local-docker") {
846	          dockerInFlight = Math.max(0, dockerInFlight - reapResult.dispatched);
847	        }
848	        emit({ type: "reap_cycle_complete", dispatched: reapResult.dispatched, failed: reapResult.failed });
849	        if (outcome === "idle") outcome = "ran_task";
850	      }
851	    } catch (e) {
852	      emit({ type: "reap_loop_error", details: String(e) });
853	    }
854	
855	    return outcome;
856	  }
857	
858	  await runAgentLoop({ config, runCycle: runOneCycle, emit, scheduler: ports.scheduler });
859	  return 0;
860	}
861	
862	main()
863	  .then((code) => process.exit(code))
864	  .catch((e) => {
865	    try {
866	      console.log(JSON.stringify({
867	        type: "fatal_error",
868	        details: (e as Error).message ?? String(e),
869	        at: new Date().toISOString(),
870	      }));
871	    } catch { /* last resort */ }
872	    process.exit(4);
873	  });
874

