1	/**
2	 * Handoff Trigger (T9) — fires after the Auto-Done Writer marks the last task done.
3	 *
4	 * Steps:
5	 *   1. Read all task YAMLs for the feature and collect completed task metadata.
6	 *   2. Generate docs/features/{featureId}/handoffs/handoff.md.
7	 *   3. Commit handoff.md to the feature branch and push.
8	 *   4. Promote draft PR to ready-for-review (or create if missing).
9	 *   5. Write handoff_pr_url, transition feature_status/current_stage in status.yaml.
10	 *   6. Commit and push status.yaml changes.
11	 *   7. Notify operator via SLACK_WEBHOOK_URL (if set).
12	 *   8. Emit feature_handoff_triggered and handoff_pr_opened events.
13	 */
14	
15	import process from "node:process";
16	import { execSync, spawnSync } from "node:child_process";
17	import {
18	  existsSync,
19	  mkdirSync,
20	  readdirSync,
21	  readFileSync,
22	  writeFileSync,
23	} from "node:fs";
24	import { join } from "node:path";
25	import { parse as parseYaml, stringify as yamlStringify } from "yaml";
26	import { buildGitEnv } from "../git-env.js";
27	import {
28	  featureBranchName,
29	  featuresRoot,
30	  statusYamlAbsPath,
31	  statusYamlRelPath,
32	  TASKS_DIR,
33	} from "../paths.js";
34	import { curlJson } from "../utils/curl-json.js";
35	import type { Task } from "../types/task.js";
36	
37	// ── Types ─────────────────────────────────────────────────────────────────────
38	
39	export interface HandoffTriggerOpts {
40	  workspaceRoot: string;
41	  featureId: string;
42	  /** Feature branch base branch (e.g. "main"). */
43	  baseBranch: string;
44	  /** GitHub personal access token for PR creation. */
45	  githubToken: string;
46	  /** GitHub owner extracted from management repo SSH URL. */
47	  repoOwner: string;
48	  /** GitHub repo name extracted from management repo SSH URL. */
49	  repoName: string;
50	  gitAuthorEmail: string;
51	  gitAuthorName?: string;
52	  sshKeyPath?: string;
53	  emit: (event: Record<string, unknown>) => void;
54	}
55	
56	export interface HandoffTriggerResult {
57	  /** Error string if the operation failed; undefined on success. */
58	  error?: string;
59	  /** URL of the opened feature branch PR. */
60	  prUrl?: string;
61	}
62	
63	interface StatusYaml {
64	  feature_status?: string;
65	  current_stage?: string;
66	  handoff_pr_url?: string | null;
67	  stages?: {
68	    handoff?: {
69	      review_status?: string;
70	      pr_url?: string | null;
71	      [key: string]: unknown;
72	    };
73	    [key: string]: unknown;
74	  };
75	  [key: string]: unknown;
76	}
77	
78	// ── Helpers ───────────────────────────────────────────────────────────────────
79	
80	function execGit(
81	  cmd: string,
82	  env: NodeJS.ProcessEnv,
83	  cwd: string,
84	): string {
85	  return execSync(cmd, {
86	    cwd,
87	    env,
88	    encoding: "utf-8",
89	    stdio: "pipe",
90	    timeout: 60_000,
91	  }).trim();
92	}
93	
94	/**
95	 * Read all task YAMLs for a feature directory.
96	 * Returns an empty array if the tasks directory does not exist.
97	 */
98	function readAllTasks(workspaceRoot: string, featureId: string): Task[] {
99	  const tasksDir = join(featuresRoot(workspaceRoot), featureId, TASKS_DIR);
100	  let files: string[] = [];
101	  try {
102	    files = readdirSync(tasksDir).filter((f) => /^T\d+\.yaml$/.test(f));
103	  } catch {
104	    return [];
105	  }
106	  const tasks: Task[] = [];
107	  for (const file of files) {
108	    try {
109	      tasks.push(parseYaml(readFileSync(join(tasksDir, file), "utf-8")) as Task);
110	    } catch {
111	      /* skip unreadable files */
112	    }
113	  }
114	  return tasks;
115	}
116	
117	/**
118	 * Read product-spec.md for the feature and extract a brief summary.
119	 * Returns a placeholder if the file is missing or unreadable.
120	 */
121	function readProductSpecSummary(workspaceRoot: string, featureId: string): string {
122	  const specPath = join(featuresRoot(workspaceRoot), featureId, "product-spec.md");
123	  if (!existsSync(specPath)) return "_No product spec found._";
124	  try {
125	    const content = readFileSync(specPath, "utf-8");
126	    // Extract first non-empty paragraph after the first heading.
127	    const lines = content.split("\n");
128	    let inContent = false;
129	    const summaryLines: string[] = [];
130	    for (const line of lines) {
131	      if (!inContent && line.startsWith("#")) { inContent = true; continue; }
132	      if (!inContent) continue;
133	      if (line.trim() === "" && summaryLines.length > 0) break;
134	      if (line.trim() !== "") summaryLines.push(line.trim());
135	    }
136	    return summaryLines.length > 0 ? summaryLines.join(" ") : "_See product spec for details._";
137	  } catch {
138	    return "_Error reading product spec._";
139	  }
140	}
141	
142	/**
143	 * Aggregate files changed across all task PRs using the GitHub Compare API.
144	 * Returns a markdown list; falls back to a placeholder when no PRs are available.
145	 */
146	async function fetchFilesChanged(
147	  tasks: Task[],
148	  githubToken: string,
149	  repoOwner: string,
150	  repoName: string,
151	): Promise<string> {
152	  const fileSet = new Set<string>();
153	  for (const task of tasks) {
154	    const prUrl = task.pr?.url;
155	    if (!prUrl) continue;
156	    const prMatch = /\/pull\/(\d+)$/.exec(prUrl);
157	    if (!prMatch) continue;
158	    const prNumber = prMatch[1];
159	    try {
160	      const files = curlJson([
161	        "-s",
162	        "-H", `Authorization: token ${githubToken}`,
163	        "-H", "Accept: application/vnd.github+json",
164	        `https://api.github.com/repos/${repoOwner}/${repoName}/pulls/${prNumber}/files`,
165	      ]) as Array<{ filename: string }>;
166	      if (Array.isArray(files)) {
167	        for (const f of files) {
168	          if (f.filename) fileSet.add(f.filename);
169	        }
170	      }
171	    } catch {
172	      /* non-fatal — skip this PR's files */
173	    }
174	  }
175	  if (fileSet.size === 0) return "_No PR file data available._";
176	  return [...fileSet].sort().map((f) => `- \`${f}\``).join("\n");
177	}
178	
179	/**
180	 * Extract reviewer notes from the last reviewer_complete log entry (if any).
181	 */
182	function extractReviewerNotes(task: Task): string {
183	  const entry = [...task.log].reverse().find((e) => e.action === "reviewer_complete");
184	  return entry?.note ? String(entry.note) : "—";
185	}
186	
187	/**
188	 * Generate the handoff document markdown from task data.
189	 */
190	async function generateHandoffDoc(
191	  opts: HandoffTriggerOpts,
192	  tasks: Task[],
193	  featureTitle: string,
194	): Promise<string> {
195	  const { workspaceRoot, featureId, githubToken, repoOwner, repoName } = opts;
196	
197	  const summary = readProductSpecSummary(workspaceRoot, featureId);
198	
199	  // Tasks Completed table
200	  const taskRows = tasks
201	    .filter((t) => t.status === "done")
202	    .map((t) => {
203	      const prUrl = t.pr?.url ? `[PR](${t.pr.url})` : "—";
204	      const notes = extractReviewerNotes(t);
205	      return `| ${t.id} — ${t.title} | ${prUrl} | ${notes} |`;
206	    })
207	    .join("\n");
208	
209	  // Files changed
210	  const filesChanged = await fetchFilesChanged(tasks, githubToken, repoOwner, repoName);
211	
212	  // Audit trail
213	  const auditRows = tasks
214	    .flatMap((t) =>
215	      t.log.map((entry) => ({
216	        action: `${t.id}: ${entry.action}`,
217	        actor: entry.by,
218	        at: entry.at,
219	      })),
220	    )
221	    .sort((a, b) => a.at.localeCompare(b.at))
222	    .map((e) => `| ${e.action} | ${e.actor} | ${e.at} |`)
223	    .join("\n");
224	
225	  // Cancelled tasks (follow-up items)
226	  const cancelledTasks = tasks.filter((t) => t.status === "cancelled");
227	  const followUp = cancelledTasks.length > 0
228	    ? cancelledTasks.map((t) => `- ${t.id} — ${t.title} (cancelled)`).join("\n")
229	    : "_None identified._";
230	
231	  return [
232	    `# Handoff — ${featureTitle}`,
233	    "",
234	    "## Summary",
235	    summary,
236	    "",
237	    "## Tasks Completed",
238	    "| Task | PR | Reviewer Notes |",
239	    "|---|---|---|",
240	    taskRows || "| — | — | — |",
241	    "",
242	    "## Deviations from Technical Design",
243	    "_See reviewer notes in Tasks Completed table above._",
244	    "",
245	    "## Files Changed",
246	    filesChanged,
247	    "",
248	    "## Follow-up Items",
249	    followUp,
250	    "",
251	    "## Audit Trail",
252	    "| Action | Actor | Timestamp |",
253	    "|---|---|---|",
254	    auditRows || "| — | — | — |",
255	  ].join("\n");
256	}
257	
258	/**
259	 * Promote the feature branch PR from draft to ready-for-review.
260	 *
261	 * Primary path: read `handoff_pr_url` from status.yaml, extract the PR number,
262	 * call PATCH to mark `draft: false`.
263	 *
264	 * Safety net: if `handoff_pr_url` is null or the PATCH returns no html_url,
265	 * fall back to searching for an open PR by head branch, then creating one fresh.
266	 */
267	function promoteOrCreateFeaturePr(opts: {
268	  featureId: string;
269	  featureBranch: string;
270	  baseBranch: string;
271	  githubToken: string;
272	  repoOwner: string;
273	  repoName: string;
274	  existingPrUrl: string | null | undefined;
275	  title: string;
276	  body: string;
277	}): { prUrl: string; alreadyExisted: boolean } {
278	  const { featureBranch, baseBranch, githubToken, repoOwner, repoName, existingPrUrl, title, body } = opts;
279	
280	  // Primary path — convert stored draft PR to ready-for-review
281	  if (existingPrUrl) {
282	    const prMatch = /\/pull\/(\d+)$/.exec(existingPrUrl);
283	    if (prMatch) {
284	      const prNumber = prMatch[1];
285	      const patchUrl = `https://api.github.com/repos/${repoOwner}/${repoName}/pulls/${prNumber}`;
286	      const patched = curlJson([
287	        "-s", "-X", "PATCH",
288	        "-H", `Authorization: token ${githubToken}`,
289	        "-H", "Accept: application/vnd.github+json",
290	        "-H", "Content-Type: application/json",
291	        "-d", JSON.stringify({ draft: false }),
292	        patchUrl,
293	      ]) as { html_url?: string };
294	
295	      if (patched.html_url) {
296	        return { prUrl: patched.html_url, alreadyExisted: true };
297	      }
298	    }
299	  }
300	
301	  // Safety net — search for existing open PR by head branch
302	  const encodedHead = encodeURIComponent(`${repoOwner}:${featureBranch}`);
303	  const listUrl = `https://api.github.com/repos/${repoOwner}/${repoName}/pulls?head=${encodedHead}&state=open`;
304	  const existing = curlJson([
305	    "-s",
306	    "-H", `Authorization: token ${githubToken}`,
307	    "-H", "Accept: application/vnd.github+json",
308	    listUrl,
309	  ]) as Array<{ html_url: string }>;
310	
311	  if (Array.isArray(existing) && existing.length > 0) {
312	    return { prUrl: existing[0].html_url, alreadyExisted: true };
313	  }
314	
315	  // Last resort — create a fresh non-draft PR
316	  const createUrl = `https://api.github.com/repos/${repoOwner}/${repoName}/pulls`;
317	  const created = curlJson([
318	    "-s", "-X", "POST",
319	    "-H", `Authorization: token ${githubToken}`,
320	    "-H", "Accept: application/vnd.github+json",
321	    "-H", "Content-Type: application/json",
322	    "-d", JSON.stringify({ title, body, head: featureBranch, base: baseBranch }),
323	    createUrl,
324	  ]) as { html_url?: string };
325	
326	  if (!created.html_url) {
327	    throw new Error(`GitHub API PR creation failed: ${JSON.stringify(created)}`);
328	  }
329	
330	  return { prUrl: created.html_url, alreadyExisted: false };
331	}
332	
333	/**
334	 * Post a Slack notification for the handoff.
335	 */
336	async function postHandoffSlack(
337	  opts: HandoffTriggerOpts,
338	  featureTitle: string,
339	  prUrl: string,
340	  webhookUrl: string,
341	): Promise<void> {
342	  const payload = {
343	    text: `[Handoff] Feature ${opts.featureId} is ready for review`,
344	    blocks: [
345	      {
346	        type: "header",
347	        text: { type: "plain_text", text: `✅ Feature handoff: ${featureTitle}` },
348	      },
349	      {
350	        type: "section",
351	        fields: [
352	          { type: "mrkdwn", text: `*Feature:*\n${opts.featureId}` },
353	          { type: "mrkdwn", text: `*Handoff PR:*\n<${prUrl}|View PR>` },
354	        ],
355	      },
356	      {
357	        type: "section",
358	        text: {
359	          type: "mrkdwn",
360	          text: "_All tasks are complete. The handoff document has been generated and a PR is open for review._",
361	        },
362	      },
363	    ],
364	  };
365	  const resp = await fetch(webhookUrl, {
366	    method: "POST",
367	    headers: { "Content-Type": "application/json" },
368	    body: JSON.stringify(payload),
369	  });
370	  if (!resp.ok) {
371	    throw new Error(`Slack webhook returned ${resp.status}: ${await resp.text()}`);
372	  }
373	}
374	
375	// ── Public API ────────────────────────────────────────────────────────────────
376	
377	/**
378	 * Fire the Handoff Trigger for a feature whose last task was just marked done.
379	 *
380	 * Non-throwing: returns an error string on failure so the caller can decide
381	 * how to surface the error.
382	 */
383	export async function fireHandoffTrigger(
384	  opts: HandoffTriggerOpts,
385	): Promise<HandoffTriggerResult> {
386	  const {
387	    workspaceRoot,
388	    featureId,
389	    baseBranch,
390	    githubToken,
391	    repoOwner,
392	    repoName,
393	    gitAuthorEmail,
394	    gitAuthorName = gitAuthorEmail,
395	    sshKeyPath,
396	    emit,
397	  } = opts;
398	
399	  const featureBranch = featureBranchName(featureId);
400	  const env = buildGitEnv(sshKeyPath, { email: gitAuthorEmail, name: gitAuthorName });
401	
402	  emit({ type: "feature_handoff_triggered", feature_id: featureId });
403	
404	  // ── Step 1: Checkout feature branch ──────────────────────────────────────
405	  try {
406	    execGit("git fetch origin", env, workspaceRoot);
407	    execGit(
408	      `git checkout -B "${featureBranch}" "origin/${featureBranch}"`,
409	      env,
410	      workspaceRoot,
411	    );
412	  } catch (e) {
413	    return { error: `Failed to checkout feature branch: ${String(e)}` };
414	  }
415	
416	  // ── Step 2: Read all task YAMLs ───────────────────────────────────────────
417	  const tasks = readAllTasks(workspaceRoot, featureId);
418	  if (tasks.length === 0) {
419	    return { error: `No task YAMLs found for feature "${featureId}"` };
420	  }
421	
422	  // Read feature title from status.yaml (or fall back to featureId)
423	  let featureTitle = featureId;
424	  const statusPath = statusYamlAbsPath(workspaceRoot, featureId);
425	  let statusYaml: StatusYaml = {};
426	  if (existsSync(statusPath)) {
427	    try {
428	      statusYaml = parseYaml(readFileSync(statusPath, "utf-8")) as StatusYaml;
429	      if (typeof statusYaml.title === "string") featureTitle = statusYaml.title;
430	    } catch {
431	      /* use featureId as fallback */
432	    }
433	  }
434	
435	  // ── Step 3: Generate handoff.md ───────────────────────────────────────────
436	  let handoffContent: string;
437	  try {
438	    handoffContent = await generateHandoffDoc(opts, tasks, featureTitle);
439	  } catch (e) {
440	    return { error: `Failed to generate handoff document: ${String(e)}` };
441	  }
442	
443	  const handoffsDir = join(featuresRoot(workspaceRoot), featureId, "handoffs");
444	  const handoffPath = join(handoffsDir, "handoff.md");
445	  const handoffRelPath = join("docs", "features", featureId, "handoffs", "handoff.md");
446	
447	  try {
448	    mkdirSync(handoffsDir, { recursive: true });
449	    writeFileSync(handoffPath, handoffContent, "utf-8");
450	  } catch (e) {
451	    return { error: `Failed to write handoff.md: ${String(e)}` };
452	  }
453	
454	  // ── Step 4: Commit handoff.md ─────────────────────────────────────────────
455	  try {
456	    execGit(`git add "${handoffRelPath}"`, env, workspaceRoot);
457	    execGit(
458	      `git commit -m "chore(${featureId}): generate handoff document"`,
459	      env,
460	      workspaceRoot,
461	    );
462	  } catch (e) {
463	    const stderr = (e as { stderr?: string }).stderr ?? String(e);
464	    if (!stderr.includes("nothing to commit")) {
465	      return { error: `Failed to commit handoff.md: ${String(e)}` };
466	    }
467	  }
468	
469	  // ── Step 5: Promote draft PR to ready-for-review (or create if missing) ─────
470	  let prUrl: string;
471	  let alreadyExisted: boolean;
472	  try {
473	    const prResult = promoteOrCreateFeaturePr({
474	      featureId,
475	      featureBranch,
476	      baseBranch,
477	      githubToken,
478	      repoOwner,
479	      repoName,
480	      existingPrUrl: statusYaml.handoff_pr_url ?? null,
481	      title: `feat(${featureId}): handoff — ${featureTitle}`,
482	      body: `## Feature Handoff\n\nFeature: \`${featureId}\`\nBranch: \`${featureBranch}\`\n\nAll tasks are complete. This PR merges the feature branch into \`${baseBranch}\`.`,
483	    });
484	    prUrl = prResult.prUrl;
485	    alreadyExisted = prResult.alreadyExisted;
486	  } catch (e) {
487	    return { error: `Failed to promote/open feature PR: ${String(e)}` };
488	  }
489	
490	  emit({
491	    type: "handoff_pr_opened",
492	    feature_id: featureId,
493	    pr_url: prUrl,
494	    already_existed: alreadyExisted,
495	  });
496	
497	  // ── Step 6: Update status.yaml ────────────────────────────────────────────
498	  try {
499	    statusYaml.handoff_pr_url = prUrl;
500	    statusYaml.feature_status = "in_handoff";
501	    statusYaml.current_stage = "handoff";
502	    if (statusYaml.stages?.handoff) {
503	      statusYaml.stages.handoff.pr_url = prUrl;
504	    }
505	    writeFileSync(statusPath, yamlStringify(statusYaml), "utf-8");
506	
507	    const statusRelPath = statusYamlRelPath(featureId);
508	    execGit(`git add "${statusRelPath}"`, env, workspaceRoot);
509	    try {
510	      execGit(
511	        `git commit -m "chore(${featureId}): transition to in_handoff; record handoff PR"`,
512	        env,
513	        workspaceRoot,
514	      );
515	    } catch (e) {
516	      const stderr = (e as { stderr?: string }).stderr ?? String(e);
517	      if (!stderr.includes("nothing to commit")) throw e;
518	    }
519	  } catch (e) {
520	    // Non-fatal — PR is already open; log but don't fail.
521	    emit({
522	      type: "handoff_status_yaml_update_failed",
523	      feature_id: featureId,
524	      details: String(e),
525	    });
526	  }
527	
528	  // ── Step 7: Push feature branch ───────────────────────────────────────────
529	  const push = spawnSync("git", ["-C", workspaceRoot, "push", "origin", featureBranch], {
530	    env,
531	    encoding: "utf-8",
532	  });
533	  if (push.status !== 0) {
534	    emit({
535	      type: "handoff_push_failed",
536	      feature_id: featureId,
537	      details: push.stderr,
538	    });
539	    // Non-fatal — the handoff doc and PR are still created.
540	  }
541	
542	  // ── Step 8: Slack notification ────────────────────────────────────────────
543	  const webhookUrl = process.env["SLACK_WEBHOOK_URL"];
544	  if (webhookUrl) {
545	    try {
546	      await postHandoffSlack(opts, featureTitle, prUrl, webhookUrl);
547	    } catch (e) {
548	      emit({
549	        type: "handoff_slack_failed",
550	        feature_id: featureId,
551	        error: String(e),
552	      });
553	    }
554	  } else {
555	    emit({ type: "handoff_slack_skipped", feature_id: featureId });
556	  }
557	
558	  return { prUrl };
559	}
