63	/**
64	 * Extract GitHub owner and repo name from an SSH remote URL.
65	 *
66	 * Accepts:
67	 *   git@github.com:owner/repo.git
68	 *   git@github.com:owner/repo
69	 *
70	 * Throws a descriptive error for non-matching URLs (e.g. HTTPS or malformed).
71	 */
72	export function parseGitHubCoords(sshUrl: string): { owner: string; repo: string } {
73	  const match = /git@github\.com:([^/]+)\/([^.]+)(?:\.git)?$/.exec(sshUrl);
74	  if (!match) {
75	    throw new Error(
76	      `Cannot parse GitHub owner/repo from URL: "${sshUrl}". ` +
77	        `Expected SSH format: git@github.com:<owner>/<repo>[.git]`,
78	    );
79	  }
80	  return { owner: match[1], repo: match[2] };

