1	/**
2	 * Tests for T9 — handoff-trigger.ts
3	 *
4	 * 1. All tasks done → fireHandoffTrigger generates handoff.md, opens PR, updates status.yaml,
5	 *    emits feature_handoff_triggered and handoff_pr_opened.
6	 * 2. Some tasks cancelled + rest done → trigger still fires.
7	 * 3. One task still in_progress → trigger must NOT fire (tested via dispatchReviewResult).
8	 * 4. Slack webhook absent → emits handoff_slack_skipped.
9	 * 5. Slack webhook present → posts to webhook.
10	 * 6. Slack POST failure → emits handoff_slack_failed but does not fail the trigger.
11	 * 7. Draft PR in status.yaml → PATCH to convert draft to ready; no new PR created.
12	 * 8. No draft PR in status.yaml (null) → falls back to search-or-create path.
13	 */
14	
15	import { describe, it, expect, vi, beforeEach, afterEach } from "vitest";
16	import {
17	  mkdtempSync,
18	  mkdirSync,
19	  writeFileSync,
20	  readFileSync,
