27	import type { Task } from "../src/types/task.js";
28	
29	// ── Mock child_process ────────────────────────────────────────────────────────
30	
31	vi.mock("node:child_process", async (importOriginal) => {
32	  const actual = await importOriginal<typeof import("node:child_process")>();
33	  return { ...actual, execSync: vi.fn(), spawnSync: vi.fn() };
34	});
35	
36	// ── Mock curlJson to avoid real curl dependency ───────────────────────────────
37	
38	vi.mock("../src/utils/curl-json.js", () => ({
39	  curlJson: vi.fn(),
40	}));
41	
42	// ── Fixtures ──────────────────────────────────────────────────────────────────
43	
44	const FEATURE_ID = "test-handoff-feature";
45	const FEATURE_BRANCH = `feature/${FEATURE_ID}`;
46	const BASE_BRANCH = "main";
47	const GITHUB_TOKEN = "ghp_test_token";
48	const REPO_OWNER = "test-owner";
49	const REPO_NAME = "test-repo";
50	const HANDOFF_PR_URL = "https://github.com/test-owner/test-repo/pull/99";
51	const ORIGINAL_SLACK_URL = process.env["SLACK_WEBHOOK_URL"];
52	
53	function makeTask(id: string, overrides: Partial<Task> = {}): Task {
54	  return {
55	    id,
56	    title: `Task ${id}`,
57	    repo: "workflow",
58	    status: "done",
59	    depends_on: [],
60	    blocked_reason: null,
61	    blocked_context: null,
62	    branch: `feature/${FEATURE_ID}-${id}`,
63	    execution: { actor_type: "agent", last_updated_by: "bot@test.com", last_updated_at: "2026-05-08T00:00:00Z" },
64	    pr: { url: `https://github.com/${REPO_OWNER}/${REPO_NAME}/pull/${parseInt(id.slice(1))}`, status: "merged" },
65	    workspace_pr: null,
66	    log: [
67	      { action: "done", by: "bot@test.com", at: "2026-05-08T10:00:00Z", note: "Done." },
68	    ],
69	    ...overrides,
70	  };
71	}
72	
73	function makeStatusYaml(): Record<string, unknown> {
74	  return {
75	    feature_id: FEATURE_ID,
76	    title: "Test Handoff Feature",
77	    feature_status: "ready_for_implementation",
78	    current_stage: "tasks",
79	    feature_branch: FEATURE_BRANCH,
80	    feature_branch_base_sha: "abc123",
81	    handoff_pr_url: null,
82	    drift_detected: false,
83	    drift_reason: null,
84	    stages: {
85	      handoff: {
86	        review_status: "draft",
87	        reviewed_by: null,
88	        reviewed_at: null,
89	        pr_url: null,
90	      },
91	    },
92	  };
93	}
94	
95	// ── Temp workspace helpers ─────────────────────────────────────────────────────
96	
97	const tmpDirs: string[] = [];
98	
99	function makeWorkspace(tasks: Task[], withStatusYaml = true): string {
100	  const wsDir = mkdtempSync(join(tmpdir(), "handoff-trigger-"));
101	  tmpDirs.push(wsDir);
102	
103	  const tasksDir = join(wsDir, "docs", "features", FEATURE_ID, "tasks");
104	  mkdirSync(tasksDir, { recursive: true });
105	
106	  for (const task of tasks) {
107	    writeFileSync(join(tasksDir, `${task.id}.yaml`), yamlStringify(task), "utf-8");
108	  }
109	
110	  if (withStatusYaml) {
111	    const statusPath = join(wsDir, "docs", "features", FEATURE_ID, "status.yaml");
112	    writeFileSync(statusPath, yamlStringify(makeStatusYaml()), "utf-8");
113	  }
