/**
 * Tests for T9 — handoff-trigger.ts
 *
 * 1. All tasks done → fireHandoffTrigger generates handoff.md, opens PR, updates status.yaml,
 *    emits feature_handoff_triggered and handoff_pr_opened.
 * 2. Some tasks cancelled + rest done → trigger still fires.
 * 3. One task still in_progress → trigger must NOT fire (tested via dispatchReviewResult).
 * 4. Slack webhook absent → emits handoff_slack_skipped.
 * 5. Slack webhook present → posts to webhook.
 * 6. Slack POST failure → emits handoff_slack_failed but does not fail the trigger.
 * 7. Draft PR in status.yaml → PATCH to convert draft to ready; no new PR created.
 * 8. No draft PR in status.yaml (null) → falls back to search-or-create path.
 */

import { describe, it, expect, vi, beforeEach, afterEach } from "vitest";
import {
  mkdtempSync,
  mkdirSync,
  writeFileSync,
  readFileSync,
  rmSync,
  existsSync,
} from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { stringify as yamlStringify, parse as parseYaml } from "yaml";
import type { Task } from "../src/types/task.js";

// ── Mock child_process ────────────────────────────────────────────────────────

vi.mock("node:child_process", async (importOriginal) => {
  const actual = await importOriginal<typeof import("node:child_process")>();
  return { ...actual, execSync: vi.fn(), spawnSync: vi.fn() };
});

// ── Mock curlJson to avoid real curl dependency ───────────────────────────────

vi.mock("../src/utils/curl-json.js", () => ({
  curlJson: vi.fn(),
}));

// ── Fixtures ──────────────────────────────────────────────────────────────────

const FEATURE_ID = "test-handoff-feature";
const FEATURE_BRANCH = `feature/${FEATURE_ID}`;
const BASE_BRANCH = "main";
const GITHUB_TOKEN = "ghp_test_token";
const REPO_OWNER = "test-owner";
const REPO_NAME = "test-repo";
const HANDOFF_PR_URL = "https://github.com/test-owner/test-repo/pull/99";
const ORIGINAL_SLACK_URL = process.env["SLACK_WEBHOOK_URL"];

function makeTask(id: string, overrides: Partial<Task> = {}): Task {
  return {
    id,
    title: `Task ${id}`,
    repo: "workflow",
    status: "done",
    depends_on: [],
    blocked_reason: null,
    blocked_context: null,
    branch: `feature/${FEATURE_ID}-${id}`,
    execution: { actor_type: "agent", last_updated_by: "bot@test.com", last_updated_at: "2026-05-08T00:00:00Z" },
    pr: { url: `https://github.com/${REPO_OWNER}/${REPO_NAME}/pull/${parseInt(id.slice(1))}`, status: "merged" },
    workspace_pr: null,
    log: [
      { action: "done", by: "bot@test.com", at: "2026-05-08T10:00:00Z", note: "Done." },
    ],
    ...overrides,
  };
}

function makeStatusYaml(): Record<string, unknown> {
  return {
    feature_id: FEATURE_ID,
    title: "Test Handoff Feature",
    feature_status: "ready_for_implementation",
    current_stage: "tasks",
    feature_branch: FEATURE_BRANCH,
    feature_branch_base_sha: "abc123",
    handoff_pr_url: null,
    drift_detected: false,
    drift_reason: null,
    stages: {
      handoff: {
        review_status: "draft",
        reviewed_by: null,
        reviewed_at: null,
        pr_url: null,
      },
    },
  };
}

// ── Temp workspace helpers ─────────────────────────────────────────────────────

const tmpDirs: string[] = [];

function makeWorkspace(tasks: Task[], withStatusYaml = true): string {
  const wsDir = mkdtempSync(join(tmpdir(), "handoff-trigger-"));
  tmpDirs.push(wsDir);

  const tasksDir = join(wsDir, "docs", "features", FEATURE_ID, "tasks");
  mkdirSync(tasksDir, { recursive: true });

  for (const task of tasks) {
    writeFileSync(join(tasksDir, `${task.id}.yaml`), yamlStringify(task), "utf-8");
  }

  if (withStatusYaml) {
    const statusPath = join(wsDir, "docs", "features", FEATURE_ID, "status.yaml");
    writeFileSync(statusPath, yamlStringify(makeStatusYaml()), "utf-8");
  }

  const specPath = join(wsDir, "docs", "features", FEATURE_ID, "product-spec.md");
  writeFileSync(specPath, "# Test Feature\n\nThis feature implements autonomous task orchestration.\n", "utf-8");

  return wsDir;
}

/** Set up curlJson mock: no existing PR → create new PR; file listing returns files. */
function setupCurlMock(curlJson: ReturnType<typeof vi.fn>, existingPrUrl?: string) {
  curlJson.mockImplementation((args: string[]) => {
    const lastArg = args[args.length - 1] ?? "";
    if (lastArg.includes("/files")) {
      return [
        { filename: "runtime/orchestrator/src/handoff/handoff-trigger.ts" },
        { filename: "runtime/orchestrator/tests/handoff-trigger.test.ts" },
      ];
    }
    if (args.includes("PATCH")) {
      // Draft → ready-for-review conversion
      return { html_url: HANDOFF_PR_URL, number: 99 };
    }
    if (lastArg.includes("state=open")) {
      return existingPrUrl ? [{ html_url: existingPrUrl, number: 99 }] : [];
    }
    // PR creation response
    return { html_url: HANDOFF_PR_URL, number: 99 };
  });
}

// ── Setup / teardown ──────────────────────────────────────────────────────────

beforeEach(() => {
  delete process.env["SLACK_WEBHOOK_URL"];
});

afterEach(() => {
  if (ORIGINAL_SLACK_URL !== undefined) {
    process.env["SLACK_WEBHOOK_URL"] = ORIGINAL_SLACK_URL;
  } else {
    delete process.env["SLACK_WEBHOOK_URL"];
  }
  while (tmpDirs.length) {
    const d = tmpDirs.pop()!;
    try { rmSync(d, { recursive: true, force: true }); } catch { /* best-effort */ }
  }
  vi.clearAllMocks();
  vi.resetModules();
  vi.unstubAllGlobals();
});

// ── Tests ─────────────────────────────────────────────────────────────────────

describe("fireHandoffTrigger — all tasks done", () => {
  it("generates handoff.md, opens PR, updates status.yaml, emits correct events", async () => {
    const tasks = [makeTask("T1"), makeTask("T2"), makeTask("T3")];
    const wsDir = makeWorkspace(tasks);

    const { execSync, spawnSync } = await import("node:child_process");
    vi.mocked(execSync).mockImplementation(() => "");
    vi.mocked(spawnSync).mockReturnValue({ pid: 0, output: [], stdout: "", stderr: "", status: 0, signal: null } as unknown as ReturnType<typeof spawnSync>);

    const { curlJson } = await import("../src/utils/curl-json.js");
    setupCurlMock(vi.mocked(curlJson));

    const { fireHandoffTrigger } = await import("../src/handoff/handoff-trigger.js");
    const events: Record<string, unknown>[] = [];

    const result = await fireHandoffTrigger({
      workspaceRoot: wsDir,
      featureId: FEATURE_ID,
      baseBranch: BASE_BRANCH,
      githubToken: GITHUB_TOKEN,
      repoOwner: REPO_OWNER,
      repoName: REPO_NAME,
      gitAuthorEmail: "bot@test.com",
      emit: (e) => events.push(e),
    });

    expect(result.error).toBeUndefined();
    expect(result.prUrl).toBe(HANDOFF_PR_URL);

    // handoff.md written to disk
    const handoffPath = join(wsDir, "docs", "features", FEATURE_ID, "handoffs", "handoff.md");
    expect(existsSync(handoffPath)).toBe(true);
    const handoffContent = readFileSync(handoffPath, "utf-8");
    expect(handoffContent).toContain("# Handoff");
    expect(handoffContent).toContain("## Tasks Completed");
    expect(handoffContent).toContain("## Audit Trail");

    // status.yaml updated
    const statusPath = join(wsDir, "docs", "features", FEATURE_ID, "status.yaml");
    const statusYaml = parseYaml(readFileSync(statusPath, "utf-8")) as Record<string, unknown>;
    expect(statusYaml.handoff_pr_url).toBe(HANDOFF_PR_URL);
    expect(statusYaml.feature_status).toBe("in_handoff");
    expect(statusYaml.current_stage).toBe("handoff");

    // Events emitted
    expect(events.some((e) => e.type === "feature_handoff_triggered")).toBe(true);
    expect(events.some((e) => e.type === "handoff_pr_opened")).toBe(true);
    expect(events.some((e) => e.type === "handoff_slack_skipped")).toBe(true);

    const prEvent = events.find((e) => e.type === "handoff_pr_opened");
    expect(prEvent?.pr_url).toBe(HANDOFF_PR_URL);
    expect(prEvent?.already_existed).toBe(false);
  });
});

describe("fireHandoffTrigger — some tasks cancelled + rest done", () => {
  it("still fires the trigger when cancelled tasks are present", async () => {
    const tasks = [
      makeTask("T1"),
      makeTask("T2", { status: "cancelled", pr: { url: "", status: "not_created" } }),
      makeTask("T3"),
    ];
    const wsDir = makeWorkspace(tasks);

    const { execSync, spawnSync } = await import("node:child_process");
    vi.mocked(execSync).mockImplementation(() => "");
    vi.mocked(spawnSync).mockReturnValue({ pid: 0, output: [], stdout: "", stderr: "", status: 0, signal: null } as unknown as ReturnType<typeof spawnSync>);

    const { curlJson } = await import("../src/utils/curl-json.js");
    setupCurlMock(vi.mocked(curlJson));

    const { fireHandoffTrigger } = await import("../src/handoff/handoff-trigger.js");
    const events: Record<string, unknown>[] = [];

    const result = await fireHandoffTrigger({
      workspaceRoot: wsDir,
      featureId: FEATURE_ID,
      baseBranch: BASE_BRANCH,
      githubToken: GITHUB_TOKEN,
      repoOwner: REPO_OWNER,
      repoName: REPO_NAME,
      gitAuthorEmail: "bot@test.com",
      emit: (e) => events.push(e),
    });

    expect(result.error).toBeUndefined();
    expect(result.prUrl).toBe(HANDOFF_PR_URL);
    expect(events.some((e) => e.type === "feature_handoff_triggered")).toBe(true);
    expect(events.some((e) => e.type === "handoff_pr_opened")).toBe(true);
  });
});

describe("fireHandoffTrigger — existing open PR (idempotent, safety net path)", () => {
  it("reuses existing feature PR via head-search when handoff_pr_url is null", async () => {
    const tasks = [makeTask("T1"), makeTask("T2")];
    const wsDir = makeWorkspace(tasks);

    const { execSync, spawnSync } = await import("node:child_process");
    vi.mocked(execSync).mockImplementation(() => "");
    vi.mocked(spawnSync).mockReturnValue({ pid: 0, output: [], stdout: "", stderr: "", status: 0, signal: null } as unknown as ReturnType<typeof spawnSync>);

    const { curlJson } = await import("../src/utils/curl-json.js");
    setupCurlMock(vi.mocked(curlJson), HANDOFF_PR_URL);

    const { fireHandoffTrigger } = await import("../src/handoff/handoff-trigger.js");
    const events: Record<string, unknown>[] = [];

    const result = await fireHandoffTrigger({
      workspaceRoot: wsDir,
      featureId: FEATURE_ID,
      baseBranch: BASE_BRANCH,
      githubToken: GITHUB_TOKEN,
      repoOwner: REPO_OWNER,
      repoName: REPO_NAME,
      gitAuthorEmail: "bot@test.com",
      emit: (e) => events.push(e),
    });

    expect(result.prUrl).toBe(HANDOFF_PR_URL);
    const prEvent = events.find((e) => e.type === "handoff_pr_opened");
    expect(prEvent?.already_existed).toBe(true);
  });
});

describe("fireHandoffTrigger — draft PR promotion", () => {
  it("converts draft PR to ready-for-review when handoff_pr_url is set in status.yaml", async () => {
    const tasks = [makeTask("T1"), makeTask("T2")];
    const wsDir = makeWorkspace(tasks);

    // Seed status.yaml with a handoff_pr_url (as if lifecycle-manager set it)
    const statusPath = join(wsDir, "docs", "features", FEATURE_ID, "status.yaml");
    const statusYaml = parseYaml(readFileSync(statusPath, "utf-8")) as Record<string, unknown>;
    statusYaml.handoff_pr_url = HANDOFF_PR_URL;
    writeFileSync(statusPath, yamlStringify(statusYaml), "utf-8");

    const { execSync, spawnSync } = await import("node:child_process");
    vi.mocked(execSync).mockImplementation(() => "");
    vi.mocked(spawnSync).mockReturnValue({ pid: 0, output: [], stdout: "", stderr: "", status: 0, signal: null } as unknown as ReturnType<typeof spawnSync>);

    const { curlJson } = await import("../src/utils/curl-json.js");
    setupCurlMock(vi.mocked(curlJson));

    const { fireHandoffTrigger } = await import("../src/handoff/handoff-trigger.js");
    const events: Record<string, unknown>[] = [];

    const result = await fireHandoffTrigger({
      workspaceRoot: wsDir,
      featureId: FEATURE_ID,
      baseBranch: BASE_BRANCH,
      githubToken: GITHUB_TOKEN,
      repoOwner: REPO_OWNER,
      repoName: REPO_NAME,
      gitAuthorEmail: "bot@test.com",
      emit: (e) => events.push(e),
    });

    expect(result.error).toBeUndefined();
    expect(result.prUrl).toBe(HANDOFF_PR_URL);

    // PATCH call must have been made (draft → ready), not a fresh POST creation
    const curlCalls = vi.mocked(curlJson).mock.calls;
    const patchCall = curlCalls.find((args) => args[0].includes("PATCH"));
    expect(patchCall).toBeDefined();
    const patchArgs = patchCall![0];
    expect(patchArgs.some((a: string) => a.includes("/pulls/99"))).toBe(true);
    const body = JSON.parse(patchArgs[patchArgs.indexOf("-d") + 1]) as { draft: boolean };
    expect(body.draft).toBe(false);

    const prEvent = events.find((e) => e.type === "handoff_pr_opened");
    expect(prEvent?.already_existed).toBe(true);
  });
});

describe("fireHandoffTrigger — Slack notification", () => {
  it("posts to Slack webhook when SLACK_WEBHOOK_URL is set", async () => {
    process.env["SLACK_WEBHOOK_URL"] = "https://hooks.slack.com/services/TEST";
    const tasks = [makeTask("T1")];
    const wsDir = makeWorkspace(tasks);

    const { execSync, spawnSync } = await import("node:child_process");
    vi.mocked(execSync).mockImplementation(() => "");
    vi.mocked(spawnSync).mockReturnValue({ pid: 0, output: [], stdout: "", stderr: "", status: 0, signal: null } as unknown as ReturnType<typeof spawnSync>);

    const { curlJson } = await import("../src/utils/curl-json.js");
    setupCurlMock(vi.mocked(curlJson));

    const mockFetch = vi.fn().mockResolvedValue({ ok: true, text: async () => "ok" });
    vi.stubGlobal("fetch", mockFetch);

    const { fireHandoffTrigger } = await import("../src/handoff/handoff-trigger.js");
    const events: Record<string, unknown>[] = [];

    await fireHandoffTrigger({
      workspaceRoot: wsDir,
      featureId: FEATURE_ID,
