    expect(events.some((e) => e.type === "handoff_slack_skipped")).toBe(false);
  });

  it("emits handoff_slack_failed when Slack POST fails but does not fail the trigger", async () => {
    process.env["SLACK_WEBHOOK_URL"] = "https://hooks.slack.com/services/BAD";
    const tasks = [makeTask("T1")];
    const wsDir = makeWorkspace(tasks);

    const { execSync, spawnSync } = await import("node:child_process");
    vi.mocked(execSync).mockImplementation(() => "");
    vi.mocked(spawnSync).mockReturnValue({ pid: 0, output: [], stdout: "", stderr: "", status: 0, signal: null } as unknown as ReturnType<typeof spawnSync>);

    const { curlJson } = await import("../src/utils/curl-json.js");
    setupCurlMock(vi.mocked(curlJson));

    const mockFetch = vi.fn().mockResolvedValue({
      ok: false, status: 500, text: async () => "Internal Server Error",
